const sources = $input.all().map(i => i.json).filter(s => s && s.id);
const cfg = ($input.first().json || {}).cfg || {};
if (!sources.length) { return [{ json: { _skip: true, cfg, source_id: '', source_name: '' } }]; }

const BUFFER_DAYS = 2;
const FALLBACK_DAYS = 8;
const out = [];

for (const s of sources) {
  const source_id = s.id || '';
  const source_name = s['Source Name'] || '';
  const channel_id = s['YouTube Channel ID'] || '';
  const yt_link = s['YouTube_Links'] || '';
  if (!channel_id) { continue; }

  const lowerLink = yt_link.toLowerCase();
  let content_filter = 'all';
  if (lowerLink.includes('/shorts')) content_filter = 'shorts_only';
  else if (lowerLink.includes('/videos')) content_filter = 'videos_only';

  const lastScanned = s['YouTube_Last_Scanned'];
  let publishedAfter;
  if (lastScanned) {
    const bufferedTs = new Date(lastScanned).getTime() - (BUFFER_DAYS * 24 * 60 * 60 * 1000);
    publishedAfter = new Date(bufferedTs).toISOString().split('T')[0] + 'T00:00:00Z';
  } else {
    const fallbackTs = Date.now() - (FALLBACK_DAYS * 24 * 60 * 60 * 1000);
    publishedAfter = new Date(fallbackTs).toISOString().split('T')[0] + 'T00:00:00Z';
  }

  out.push({ json: { _skip: false, cfg, source_id, source_name, channel_id, content_filter, publishedAfter, yt_link } });
}

if (!out.length) { return [{ json: { _skip: true, cfg, source_id: '', source_name: '' } }]; }
return out;

const responses = $input.all();
const sources = $('2a. Prepare Source Input').all().map(i => i.json).filter(s => !s._skip);
const cfg = (sources[0] || {}).cfg || {};
const out = [];

for (let i = 0; i < responses.length; i++) {
  const src = sources[i];
  if (!src) continue;
  const raw = responses[i].json;
  if (!raw || raw.error || (raw.statusCode && raw.statusCode >= 400)) {
    console.log('[4] YouTube search error for ' + src.source_name);
    continue;
  }
  const items = raw.items || [];
  const ids = [...new Set(items.filter(x => x.id && x.id.videoId).map(x => x.id.videoId))];
  for (const video_id of ids) {
    out.push({ json: { video_id, cfg, source_id: src.source_id, source_name: src.source_name, channel_id: src.channel_id, content_filter: src.content_filter } });
  }
}

if (!out.length) { return [{ json: { _skip_videos: true, cfg } }]; }
return out;

const existingItems = $input.all();
const existingIds = new Set(existingItems.map(i => i.json['Video ID'] || '').filter(id => id !== ''));
const incoming = $('4. Extract Video IDs').all();
const cfg = (incoming[0] && incoming[0].json && incoming[0].json.cfg) || {};

if (incoming.length === 1 && incoming[0].json._skip_videos) {
  return [{ json: { _skip: true, cfg } }];
}

const seen = new Set();
const newVideos = [];
for (const item of incoming) {
  if (item.json._skip_videos) continue;
  const vid = item.json.video_id;
  if (!vid || existingIds.has(vid) || seen.has(vid)) continue;
  seen.add(vid);
  newVideos.push(item);
}

console.log('[6] New videos: ' + newVideos.length);
if (!newVideos.length) return [{ json: { _skip: true, cfg } }];
return newVideos;

const responses = $input.all();
const chunks = $('7b. Chunk Video IDs').all();
const sources = $('2a. Prepare Source Input').all().map(i => i.json).filter(s => !s._skip);
const cfg = (sources[0] || {}).cfg || {};

const srcByChannel = {};
for (const s of sources) { if (s.channel_id) srcByChannel[s.channel_id] = s; }

const OUTLIER_THRESHOLD = 2.0;
const YOUTUBE_SHORTFORM_BONUS = 0.5;
const currentYear = new Date().getFullYear();
const currentYearStart = currentYear + '-01-01';

function tierFor(score) {
  if (score > 5.0) return 'Tier 1: Mega-Viral';
  if (score >= 2.0) return 'Tier 2: Strong Outlier';
  return null;
}

const candidates = [];
for (let ci = 0; ci < responses.length; ci++) {
  const metadata = (responses[ci].json && responses[ci].json.items) || [];
  const chunkRecs = ((chunks[ci] && chunks[ci].json && chunks[ci].json.records) || []);
  const recByVid = {};
  for (const r of chunkRecs) recByVid[r.video_id] = r;

  for (const meta of metadata) {
    if (!meta || !meta.id) continue;
    const snippet = meta.snippet || {};
    const stats = meta.statistics || {};
    if (!snippet.publishedAt || snippet.publishedAt < currentYearStart) continue;

    const rec = recByVid[meta.id] || {};
    const chId = snippet.channelId || rec.channel_id || '';
    const src = srcByChannel[chId] || {};
    const content_filter = rec.content_filter || src.content_filter || 'all';

    const duration = (meta.contentDetails || {}).duration || 'PT0S';
    let seconds = 0;
    const m = duration.match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);
    if (m) seconds = (parseInt(m[1]||0)*3600) + (parseInt(m[2]||0)*60) + parseInt(m[3]||0);
    const isShort = content_filter === 'shorts_only' ? true : content_filter === 'videos_only' ? false : seconds <= 60;
    const contentType = isShort ? 'Short' : 'Video';
    const url = isShort ? 'https://www.youtube.com/shorts/' + meta.id : 'https://www.youtube.com/watch?v=' + meta.id;

    candidates.push({
      cfg,
      video_id: meta.id, title: snippet.title || 'Untitled', url,
      channel_id: chId, description: snippet.description || '',
      tags: Array.isArray(snippet.tags) ? snippet.tags.join(', ') : '',
      published_at: snippet.publishedAt || '',
      view_count: parseInt(stats.viewCount || 0), like_count: parseInt(stats.likeCount || 0),
      comment_count: parseInt(stats.commentCount || 0), duration: seconds,
      content_type: contentType, platform: 'YouTube',
      source_id: rec.source_id || src.source_id || '',
      source_name: rec.source_name || src.source_name || ''
    });
  }
}

if (!candidates.length) { return [{ json: { _skip: true, cfg } }]; }

function median(arr) {
  if (!arr.length) return 0;
  const s = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 === 0 ? (s[mid - 1] + s[mid]) / 2 : s[mid];
}

const historyByChannel = {};
let _existingRecs = [];
try { _existingRecs = $('5. Get All Existing Video IDs').all(); } catch (e) {}
for (const rec of _existingRecs) {
  const ch = (rec.json['Channel ID'] || '').trim();
  if (!ch) continue;
  const v = parseInt(rec.json['View Count']) || 0;
  const ts = rec.json['Published At'] || '';
  if (!historyByChannel[ch]) historyByChannel[ch] = [];
  historyByChannel[ch].push({ v, ts });
}

const currentByChannel = {};
for (const c of candidates) {
  if (!currentByChannel[c.channel_id]) currentByChannel[c.channel_id] = [];
  currentByChannel[c.channel_id].push({ v: c.view_count, ts: c.published_at });
}

const baselineByChannel = {};
const allChannels = new Set([...Object.keys(historyByChannel), ...Object.keys(currentByChannel)]);
for (const ch of allChannels) {
  const combined = [...(historyByChannel[ch] || []), ...(currentByChannel[ch] || [])]
    .filter(x => x.v > 0)
    .sort((a, b) => String(b.ts).localeCompare(String(a.ts)))
    .slice(0, 30)
    .map(x => x.v);
  baselineByChannel[ch] = median(combined);
}

const results = [];
for (const c of candidates) {
  const baseline = baselineByChannel[c.channel_id] || 0;
  const rawScore = baseline > 0 ? parseFloat((c.view_count / baseline).toFixed(2)) : 0;
  const boostedScore = parseFloat((rawScore + YOUTUBE_SHORTFORM_BONUS).toFixed(2));
  const tier = tierFor(boostedScore);
  if (!tier) continue;
  results.push({ json: { ...c, outlier_score: boostedScore, raw_outlier_score: rawScore, baseline_median: baseline, outlier_tier: tier } });
}
console.log('[8c] Outliers: ' + results.length + '/' + candidates.length);
return results.length > 0 ? results : [{ json: { _skip: true, cfg } }];

const sources = $('2a. Prepare Source Input').all().map(i => i.json).filter(s => !s._skip && s.source_id);
if (!sources.length) { return []; }
const today = new Date().toISOString().split('T')[0];
return sources.map(s => ({ json: { cfg: s.cfg, source_id: s.source_id, source_name: s.source_name, last_scanned: today } }));

const clients = $input.all().map(i => i.json);
const out = [];
for (const c of clients) {
  const name = c['Client_Name'];
  if (!name) continue;
  if (c['Video_Enabled'] !== true) continue;
  if (!c['Video_Base_ID']) continue;
  out.push({ json: { client_name: name, video_base_id: c['Video_Base_ID'] } });
}
return out;

const loop = $('0c. Client Loop');
let cfg = null;
try { cfg = loop.item.json; } catch (e) { cfg = null; }
if (!cfg || !cfg.video_base_id) { throw new Error('Could not resolve client config for this iteration.'); }
return { json: { ...$input.item.json, cfg } };

const CHUNK = 50;
const all = $input.all().map(i => i.json).filter(v => v && v.video_id);
if (!all.length) { return []; }
const out = [];
for (let i = 0; i < all.length; i += CHUNK) {
  const slice = all.slice(i, i + CHUNK);
  out.push({ json: { chunk_index: out.length, id_csv: slice.map(v => v.video_id).join(','), records: slice } });
}
return out;
